<script>
  $('[data-role="reset-referral"').on("click", function(){
    clearReff();
  });
  function clearReff() {
     window.location.href = "/cart?ref=retaildirect";
    }
    function getReferralCookie() {
      let name = "refId=";
      let decodedCookie = decodeURIComponent(document.cookie);
      let ca = decodedCookie.split(';');
      for (let i = 0; i < ca.length; i++) {
          let c = ca[i];
          while (c.charAt(0) == ' ') {
              c = c.substring(1);
          }
          if (c.indexOf(name) == 0) {
              return c.substring(name.length, c.length);
          }
      }
      return "retaildirect";
  }

  function setElement(){
