<!-- IBO Tooltip Styles -->
<style>
.ibo-tooltip {
  position: relative;
  display: inline-block;
  cursor: pointer;
  color: #f88602;
  text-decoration: underline;
}

.ibo-tooltip .ibo-tooltiptext {
  visibility: hidden;
  width: 300px;
  background-color: #fff;
  color: #000;
  text-align: left;
  border-radius: 8px;
  border: 1px solid #ccc;
  padding: 10px;
  position: absolute;
  z-index: 9999;

  /* show below instead of above */
  top: 125%;         /* position below the trigger */
  left: 50%;
  margin-left: -150px;
  box-shadow: 0 4px 8px rgba(0,0,0,0.2);

  /* add small animation for nicer feel */
  opacity: 0;
  transition: opacity 0.2s ease;
}

.ibo-tooltip:hover .ibo-tooltiptext {
  visibility: visible;
  opacity: 1;
}

  /* No referral checkbox */
