    margin-top:10px;
  }
</style>

<script>
  // Block checkout if no referral and checkbox not ticked
  document.addEventListener("DOMContentLoaded", function(){
    // Intercept checkout button clicks
    document.querySelectorAll("form[action='/cart'] button, form[action='/checkout'] button, a[href='/checkout']").forEach(function(btn){
      btn.addEventListener("click", function(e){
        var hasIBO = document.getElementById("enrollerInfo").textContent.trim() !== "";
        var noRefChecked = document.getElementById("noReferralCheckbox").checked;
        if(!hasIBO && !noRefChecked){
          e.preventDefault();
          document.getElementById("referralError").style.display = "block";
          window.scrollTo({ top: document.getElementById("noReferralContainer").offsetTop - 100, behavior: 'smooth'});
          return false;
        }
      });
    });
  });

  // Save selected IBO to cart attribute "refId"
  function saveIBOToCart(refIdValue){
    fetch('/cart/update.js', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        attributes: {
          refId: refIdValue   // <-- use same name as your cookie
        }
      })
    })
    .then(res => res.json())
    .then(data => {
      console.log('Saved refId to cart', data.attributes);
    });
  }

  // When user selects an enroller from search results:
  document.addEventListener("DOMContentLoaded", function(){
    // Click on search result link
    document.getElementById("enrollerSearchResult").addEventListener("click", function(e){
      let link = e.target.closest('a');
      if(link){
        // Get display name and ID from the clicked entry
        let entry = link.querySelector('.entry');
        let text = entry ? entry.innerText.trim() : '';
        // update UI
        document.getElementById("enrollerInfo").innerHTML = text;
        // extract the customerID if needed
        let idSpan = entry.querySelector('span');
        let refId = idSpan ? idSpan.innerText.trim() : 'retaildirect';
        // save to cart attribute
        saveIBOToCart(refId);
      }
    });

    // When user ticks "I was not referred by anyone"
    let noRefCheckbox = document.getElementById("noReferralCheckbox");
    if(noRefCheckbox){
      noRefCheckbox.addEventListener("change", function(){
        if(this.checked){
          document.getElementById("enrollerInfo").textContent = 'Retail Direct / No Referral';
          saveIBOToCart('retaildirect');
        }
      });
    }
  });
</script>

